1	package net.officefloor.hq.app.person;
2	
3	import java.time.LocalDate;
4	import java.util.List;
5	import net.officefloor.hq.app.Audit;
6	import net.officefloor.hq.app.rollup.Rollups;
7	import net.officefloor.hq.app.sheet.SheetService;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	import org.springframework.web.server.ResponseStatusException;
12	
13	/** The people kept on a sheet: listed, added and edited. */
14	@Service
15	public class PersonService {
16	
17	    private final PersonRepository people;
18	    private final SheetService sheets;
19	    private final Rollups rollups;
20	    private final Audit audit;
21	
22	    public PersonService(PersonRepository people, SheetService sheets, Rollups rollups, Audit audit) {
23	        this.people = people;
24	        this.sheets = sheets;
25	        this.rollups = rollups;
26	        this.audit = audit;
27	    }
28	
29	    /** The sheet's people in the order they were added. */
30	    @Transactional(readOnly = true)
31	    public List<Person> list(String sheetId) {
32	        return people.findBySheetIdOrderByIdAsc(sheetId);
33	    }
34	
35	    /**
36	     * Add a person to the sheet, with their own terms (null: none) and contact (null or blank: none);
37	     * refused when the name or the contact is already in use on it.
38	     */
39	    @Transactional
40	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
41	        sheets.load(sheetId);
42	        requireNameFree(sheetId, name, null);
43	        requireContactFree(sheetId, contact, null);
44	        Rollups.Rollup before = rollups.take(sheetId);
45	        Person person = people.saveAndFlush(new Person(sheetId, name, grade, terms, contact));
46	        audited("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId), terms != null,
47	                person.getContact() != null);
48	        rollups.audit(sheetId, user, before);
49	        return person;
50	    }
51	
52	    /**
53	     * Change a person's name and own terms (null: none) and record their grade from a date (null: the
54	     * sheet's today), keeping the grades already recorded, from the version of the person the editor loaded; refused when someone
55	     * has saved the person since, or when the name or contact (null or blank: none) is in use by another
56	     * person. PERSON_EDITED carries terms=&lt;terms&gt; and contact=&lt;contact&gt; only when the form gave
57	     * them or the edit changes them.
58	     */
59	    @Transactional
60	    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
61	            LocalDate gradeFrom, Integer terms, String contact, boolean termsGiven, boolean contactGiven) {
62	        Person person = people.findByIdAndSheetId(personId, sheetId)
63	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
64	        if (person.getVersion() != version) {
65	            throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
66	                    "Someone else has saved this person since it was opened.");
67	        }
68	        requireNameFree(sheetId, name, person.getId());
69	        requireContactFree(sheetId, contact, person.getId());
70	        Rollups.Rollup before = rollups.take(sheetId);
71	        LocalDate today = sheets.today(sheetId);
72	        boolean withTerms = termsGiven || !java.util.Objects.equals(person.getTerms(), terms);
73	        boolean withContact = contactGiven
74	                || !java.util.Objects.equals(person.getContact(), Person.contactOf(contact));
75	        person.setName(name);
76	        person.setTerms(terms);
77	        person.setContact(contact);
78	        person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
79	        Person saved = people.saveAndFlush(person);
80	        audited("PERSON_EDITED", sheetId, user, saved, today, withTerms, withContact);
81	        rollups.audit(sheetId, user, before);
82	        return saved;
83	    }
84	
85	    /**
86	     * Retire a person from a date; with no date, from the sheet's today. Once the sheet's today reaches
87	     * it, their OPEN and PENDING claims not bound by a statement leave the live totals.
88	     */
89	    @Transactional
90	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
91	        Person person = people.findByIdAndSheetId(personId, sheetId)
92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
93	        Rollups.Rollup before = rollups.take(sheetId);
94	        person.retire(from != null ? from : sheets.today(sheetId));
95	        Person saved = people.saveAndFlush(person);
96	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
97	                + " name=" + saved.getName() + " from=" + saved.getRetiredFrom());
98	        rollups.audit(sheetId, user, before);
99	        return saved;
100	    }
101	
102	    /**
103	     * Put a person on hold from a date (null: the sheet's today) to a date (null: no end); refused
104	     * when the to-date is before the from-date. Their figures and the sheet's totals move as their
105	     * OPEN and PENDING claims dated within it, not bound by a statement, leave the live totals.
106	     */
107	    @Transactional
108	    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
109	        Person person = people.findByIdAndSheetId(personId, sheetId)
110	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
111	        LocalDate start = from != null ? from : sheets.today(sheetId);
112	        if (to != null && to.isBefore(start)) {
113	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
114	        }
115	        Rollups.Rollup before = rollups.take(sheetId);
116	        person.hold(start, to);
117	        Person saved = people.saveAndFlush(person);
118	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
119	                + " name=" + saved.getName() + " from=" + start);
120	        rollups.audit(sheetId, user, before);
121	        return saved;
122	    }
123	
124	    /**
125	     * Name another person on the sheet as a patron of this one; refused for the person themselves and
126	     * for someone already their patron.
127	     */
128	    @Transactional
129	    public Person addPatron(String sheetId, String user, long personId, long patronId) {
130	        Person person = people.findByIdAndSheetId(personId, sheetId)
131	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
132	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
133	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
134	        if (person.getId().equals(patron.getId())) {
135	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
136	        }
137	        if (!person.addPatron(patron.getId())) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
139	        }
140	        Person saved = people.saveAndFlush(person);
141	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
142	                + " name=" + saved.getName() + " patron=" + patron.getName());
143	        return saved;
144	    }
145	
146	    /**
147	     * Record the change to the person, with the grade in force on the sheet's today and, on an edit or
148	     * an add that gave them, their own terms and contact (blank when they have none), once it is committed.
149	     */
150	    private void audited(String event, String sheetId, String user, Person person, LocalDate today,
151	            boolean withTerms, boolean withContact) {
152	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
153	                + " name=" + person.getName() + " grade=" + person.gradeOn(today)
154	                + (withTerms ? " terms=" + (person.getTerms() != null ? person.getTerms() : "") : "")
155	                + (withContact ? " contact=" + (person.getContact() != null ? person.getContact() : "") : ""));
156	    }
157	
158	    /** Refuse a contact (null or blank: none) already held on the sheet by anyone other than {@code self}. */
159	    private void requireContactFree(String sheetId, String contact, Long self) {
160	        String kept = Person.contactOf(contact);
161	        if (kept == null) {
162	            return;
163	        }
164	        people.findBySheetIdAndContact(sheetId, kept)
165	                .filter(holder -> !holder.getId().equals(self))
166	                .ifPresent(holder -> {
167	                    throw new ResponseStatusException(HttpStatus.CONFLICT,
168	                            "That contact is already in use on this sheet.");
169	                });
170	    }
171	
172	    /** Refuse a name already held on the sheet by anyone other than {@code self}. */
173	    private void requireNameFree(String sheetId, String name, Long self) {
174	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
175	                .filter(holder -> !holder.getId().equals(self))
176	                .ifPresent(holder -> {
177	                    throw nameInUse();
178	                });
179	    }
180	
181	    static ResponseStatusException nameInUse() {
182	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
183	    }
184	}
